insert into steinhart_monsters (name, challenge_rating, creature_type, book_page, summary) values
  ('Охотник в Вуали', '7', 'Аберрация', 380, 'Падший охотник-друид, сросшийся с деревьями: атаки на дистанции, тюрьма из корней, телепорт между деревьями, маска даёт сопротивление магии.'),
  ('Извращённый Библиотекарь', '11', 'Нежить', 382, 'Призрачный заклинатель-некромант (остеомантия), левитирует, аура тишины, отражает заклинания, при 0 хитов раз в день восстанавливает все хиты и часть ячеек.'),
  ('Тисифона, Первозданный Хаос', '14', 'Аберрация', 384, 'Друид-мутант из Круга Симбиоза: регенерация, легендарные действия, при 0 хитов уходит в неуязвимую сферу и возрождается.'),
  ('Малах, Ангел Плоти', '15', 'Конструкт', 386, 'Механический "ангел" в облачении из плоти убитых: ядовитые миазмы, легендарные действия, форма и способности меняются при полу-хитах.'),
  ('Король Охоты', '28', 'Гуманоид и Аберрация', 397, 'Финальный босс Падших Охотников — бессмертный воин (не теряет сознание при 0 хитов), иммунитет к немагическому физическому урону, скорость не замедлить.')
insert into steinhart_items (name, category, rarity, book_page, summary) values
  ('Проклятие Лунной Крови', 'Потусторонний орнамент', 'редкая/оч.редкая/легендарная (зависит от способа нанесения)', 258, 'Превращает владельца в багряного зверя (Луннокровного) при определённых условиях — тема каннибализма/проклятия первых жертв Бедствия.'),
  ('Свинцовая Кровь', 'Потусторонний орнамент', 'варьируется', 260, 'Связан с состоянием берсерка: при завершении эффекта хиты падают до 0 и теряются все силы орнамента на неделю.'),
  ('Жертвенное Клеймо', 'Потусторонний орнамент', 'варьируется', 260, 'Получают воскрешённые Кровавой Луной Перерождения — помечает их как связанных с ней, усиливается во время её действия.'),
  ('Потомок Молнии', 'Потусторонний орнамент', 'варьируется', 261, 'Электрическая тема — см. книгу для точных эффектов по уровням нанесения (рисунок/татуировка/шрамирование).'),
  ('Благословение Навре', 'Потусторонний орнамент', 'варьируется', 263, 'См. книгу для точных эффектов.'),
  ('Мефитовая Печать', 'Потусторонний орнамент', 'варьируется', 263, 'Связан с ядовитыми/газовыми эффектами (мефит) — см. книгу для точных эффектов.'),
  ('Первый Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Часть трилогии Первый/Второй/Третий Орнамент, тема праведного мстителя с "Клинком серафима".'),
  ('Второй Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Продолжение линейки — усиливает Праведное возмездие и позволяет слить Клинок серафима с оружием.'),
  ('Третий Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Финальная ступень линейки орнаментов серафима — см. книгу для точных эффектов.')
